<script setup lang="ts">import{ref}from'vue';import{useRenameStore}from'../stores/rename';import WorkflowRail from'../components/layout/WorkflowRail.vue';import DirectoryOverview from'../components/rename/DirectoryOverview.vue';import ResultTable from'../components/rename/ResultTable.vue';import MatchStatistics from'../components/rename/MatchStatistics.vue';import ProgressStatus from'../components/rename/ProgressStatus.vue';import ResultDetails from'../components/rename/ResultDetails.vue';import RegexTemplateDrawer from'../components/rename/RegexTemplateDrawer.vue';import SettingsDrawer from'../components/rename/SettingsDrawer.vue';import ExecuteConfirmation from'../components/rename/ExecuteConfirmation.vue';import ExecutionDetails from'../components/rename/ExecutionDetails.vue';const s=useRenameStore();const detail=ref<any>(null),detailsOpen=ref(false),templates=ref(false),settings=ref(false),confirming=ref(false),completed=ref(false);function show(item:any){detail.value=item;detailsOpen.value=true}function openTemplates(){settings.value=false;templates.value=true}function openSettings(){templates.value=false;settings.value=true}async function execute(){confirming.value=false;await s.execute();completed.value=true}</script>
<template><div class="rename-workspace"><WorkflowRail @execute="confirming=true" @templates="openTemplates" @settings="openSettings"/><main class="results"><DirectoryOverview :root="s.root" :directories="0" :files="s.progress.scannedTotal"/><ProgressStatus/><section class="table-card"><ResultTable @details="show"/><MatchStatistics/></section></main><ResultDetails v-model="detailsOpen" :item="detail"/><RegexTemplateDrawer v-model="templates"/><SettingsDrawer v-model="settings"/><ExecuteConfirmation v-model="confirming" @confirm="execute"/><ExecutionDetails v-model="completed" :operation-id="s.lastOperationId"/></div></template>
<style scoped>.rename-workspace{display:grid;grid-template-columns:minmax(300px,35%) minmax(0,65%);height:100%;margin:-20px}.results{display:grid;grid-template-rows:auto auto minmax(260px,1fr);gap:12px;min-width:0;padding:18px}.table-card{display:grid;grid-template-rows:minmax(0,1fr) auto;min-height:0;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden}@media(max-width:820px){.rename-workspace{grid-template-columns:1fr}.rename-workspace>:first-child{display:none}}</style>
